1	import { describe, it, expect } from 'vitest';
2	import { readFileSync } from 'fs';
3	import { join } from 'path';
4	import { AmexParser } from '../AmexParser';
5	
6	describe('AmexParser', () => {
7		const parser = new AmexParser();
8	
9		// Helper to load CSV files from resources
10		const loadCSV = (filename: string): string => {
11			const filePath = join(process.cwd(), 'resources', filename);
12			return readFileSync(filePath, 'utf-8');
13		};
14	
15		describe('validateFormat', () => {
16			it('should validate correct Amex CSV format', () => {
17				const csv = loadCSV('Amex-Test.csv');
18				expect(parser.validateFormat(csv)).toBe(true);
19			});
20	
21			it('should reject invalid CSV format (no Amex identifier)', () => {
22				const invalidCSV = `Date,Description,Amount
23	01/01/2024,Store,100.00`;
24				expect(parser.validateFormat(invalidCSV)).toBe(false);
25			});
26	
27			it('should reject empty CSV', () => {
28				expect(parser.validateFormat('')).toBe(false);
29			});
30	
31			it('should reject CSV without data header row', () => {
32				const invalidCSV = `American Express
33	Some other row
34	More data`;
35				expect(parser.validateFormat(invalidCSV)).toBe(false);
36			});
37	
38			it('should handle CSV with BOM', () => {
39				const csv = loadCSV('Amex-Test.csv');
40				expect(parser.validateFormat(csv)).toBe(true);
41			});
42		});
43	
44		describe('parse', () => {
45			it('should parse sample data correctly', () => {
46				const csv = loadCSV('Amex-Test.csv');
47				const result = parser.parse(csv);
48	
49				expect(result.errors).toEqual([]);
50				expect(result.transactions).toHaveLength(14);
51	
52				// Check first transaction
53				expect(result.transactions[0]).toEqual({
54					transaction_date: '2025-05-31',
55					vendor_name: 'Alcohol',
56					amount: -33.2
57				});
58	
59				// Check last transaction
60				expect(result.transactions[13]).toEqual({
61					transaction_date: '2025-05-17',
62					vendor_name: 'Online',
63					amount: -137.15
64				});
65			});
66	
67			it('should skip header rows before data', () => {
68				const csv = loadCSV('Amex-Test.csv');
69				const result = parser.parse(csv);
70	
71				// Should not include summary rows or empty rows
72				expect(result.transactions.every((t) => t.vendor_name !== 'Summary')).toBe(true);
73				expect(result.transactions.every((t) => t.vendor_name !== 'Charges & Adjustments')).toBe(
74					true
75				);
76			});
77	
78			it('should handle amounts with commas', () => {
79				const csv = loadCSV('Amex-Test.csv');
80				const result = parser.parse(csv);
81	
82				// The sample file has amounts without commas in the data section
83				// but the summary section has commas - verify data parsing works
84				expect(result.transactions.every((t) => !isNaN(t.amount))).toBe(true);
85			});
86	
87			it('should handle amounts with dollar signs', () => {
88				const csv = loadCSV('Amex-Test.csv');
89				const result = parser.parse(csv);
90	
91				// All amounts should be parsed correctly despite dollar signs
92				expect(result.transactions[0].amount).toBe(-33.2);
93				expect(result.transactions[1].amount).toBe(-41.97);
94			});
95	
96			it('should parse dates in DD-MMM-YY format', () => {
97				const csv = `American Express
98	,,,,
99	Date,Date Processed,Description,Amount,Foreign Spend Amount
100	31-May-25,01 Jun. 2025,Test Store,$100.00,`;
101				const result = parser.parse(csv);
102	
103				expect(result.transactions[0].transaction_date).toBe('2025-05-31');
104			});
105	
106			it('should handle dates with full month names', () => {
107				const csv = `American Express
108	,,,,
109	Date,Date Processed,Description,Amount,Foreign Spend Amount
110	27-May-25,27-May-25,Test Store,$50.00,`;
111				const result = parser.parse(csv);
112	
113				expect(result.transactions[0].transaction_date).toBe('2025-05-27');
114			});
115	
116			it('should report errors for invalid dates', () => {
117				const csv = `American Express
118	,,,,
119	Date,Date Processed,Description,Amount,Foreign Spend Amount
120	invalid-date,01 Jun. 2025,Test Store,$100.00,`;
121				const result = parser.parse(csv);
122	
123				expect(result.errors.length).toBeGreaterThan(0);
124				expect(result.errors[0]).toContain('Invalid date format');
125			});
126	
127			it('should report errors for invalid amounts', () => {
128				const csv = `American Express
129	,,,,
130	Date,Date Processed,Description,Amount,Foreign Spend Amount
131	31-May-25,01 Jun. 2025,Test Store,not-a-number,`;
132				const result = parser.parse(csv);
133	
134				expect(result.errors.length).toBeGreaterThan(0);
135				expect(result.errors[0]).toContain('Invalid amount');
136			});
137	
138			it('should report errors for missing description', () => {
139				const csv = `American Express
140	,,,,
141	Date,Date Processed,Description,Amount,Foreign Spend Amount
142	31-May-25,01 Jun. 2025,,$100.00,`;
143				const result = parser.parse(csv);
144	
145				expect(result.errors.length).toBeGreaterThan(0);
146				expect(result.errors[0]).toContain('Missing vendor name');
147			});
148	
149			it('should handle empty CSV', () => {
150				const result = parser.parse('');
151	
152				expect(result.transactions).toEqual([]);
153				expect(result.errors.length).toBeGreaterThan(0);
154			});
155	
156			it('should skip incomplete rows', () => {
157				const csv = `American Express
158	,,,,
159	Date,Date Processed,Description,Amount,Foreign Spend Amount
160	31-May-25,01 Jun. 2025,Test Store,$100.00,
161	Incomplete Row
162	01-Jun-25,02 Jun. 2025,Another Store,$50.00,`;
163				const result = parser.parse(csv);
164	
165				expect(result.transactions).toHaveLength(2);
166				expect(result.transactions[0].vendor_name).toBe('Test Store');
167				expect(result.transactions[1].vendor_name).toBe('Another Store');
168			});
169	
170			it('should skip empty rows', () => {
171				const csv = `American Express
172	,,,,
173	Date,Date Processed,Description,Amount,Foreign Spend Amount
174	31-May-25,01 Jun. 2025,Test Store,$100.00,
175	
176	01-Jun-25,02 Jun. 2025,Another Store,$50.00,`;
177				const result = parser.parse(csv);
178	
179				expect(result.transactions).toHaveLength(2);
180			});
181	
182			it('should handle CSV with BOM', () => {
183				const csv = loadCSV('Amex-Test.csv');
184				const result = parser.parse(csv);
185	
186				expect(result.transactions).toHaveLength(14);
187				expect(result.errors).toEqual([]);
188			});
189	
190			it('should handle amounts with spaces', () => {
191				const csv = `American Express
192	,,,,
193	Date,Date Processed,Description,Amount,Foreign Spend Amount
194	31-May-25,01 Jun. 2025,Test Store, $100.00 ,`;
195				const result = parser.parse(csv);
196	
197				expect(result.transactions[0].amount).toBe(-100.0);
198			});
199	
200			it('should handle decimal amounts', () => {
201				const csv = loadCSV('Amex-Test.csv');
202				const result = parser.parse(csv);
203	
204				// Check various decimal amounts
205				expect(result.transactions[0].amount).toBe(-33.2);
206				expect(result.transactions[1].amount).toBe(-41.97);
207				expect(result.transactions[2].amount).toBe(-16.09);
208			});
209	
210			it('should handle all transactions as negative amounts (credit card charges = expenses)', () => {
211				const csv = loadCSV('Amex-Test.csv');
212				const result = parser.parse(csv);
213	
214				// Amex charges are all negative (negative = expense)
215				expect(result.transactions.every((t) => t.amount < 0)).toBe(true);
216			});
217	
218			it('should find data header row correctly', () => {
219				const csv = `American Express Card
220	Transaction Details
221	Account Summary
222	Summary
223	Date,Date Processed,Description,Amount,Foreign Spend Amount
224	31-May-25,01 Jun. 2025,Test Store,$100.00,`;
225				const result = parser.parse(csv);
226	
227				expect(result.transactions).toHaveLength(1);
228				expect(result.transactions[0].vendor_name).toBe('Test Store');
229			});
230	
231			it('should handle extra columns after required ones', () => {
232				const csv = loadCSV('Amex-Test.csv');
233				const result = parser.parse(csv);
234	
235				// The sample file has additional columns like Foreign Spend Amount, Commission, etc.
236				// Parser should handle these gracefully
237				expect(result.errors).toEqual([]);
238				expect(result.transactions).toHaveLength(14);
239			});
240	
241			it('should trim whitespace from vendor names', () => {
242				const csv = `American Express
243	,,,,
244	Date,Date Processed,Description,Amount,Foreign Spend Amount
245	31-May-25,01 Jun. 2025,  Test Store  ,$100.00,`;
246				const result = parser.parse(csv);
247	
248				expect(result.transactions[0].vendor_name).toBe('Test Store');
249			});
250	
251			it('should handle different vendor name formats', () => {
252				const csv = loadCSV('Amex-Test.csv');
253				const result = parser.parse(csv);
254	
255				// Check various vendor name formats from the sample
256				const vendorNames = result.transactions.map((t) => t.vendor_name);
257				expect(vendorNames).toContain('Alcohol');
258				expect(vendorNames).toContain('Grocery 1');
259				expect(vendorNames).toContain('Resturant 1');
260				expect(vendorNames).toContain('Hardware store');
261			});
262	
263			it('should handle integer amounts without decimals', () => {
264				const csv = `American Express
265	,,,,
266	Date,Date Processed,Description,Amount,Foreign Spend Amount
267	31-May-25,01 Jun. 2025,Test Store,$100,`;
268				const result = parser.parse(csv);
269	
270				expect(result.transactions[0].amount).toBe(-100);
271			});
272		});
273	});
